import { Children, useEffect, useId, useRef, useState, type KeyboardEvent, type PointerEvent, type ReactNode } from 'react'
import { DEFAULT_LEFT, clampWidth, splitBounds, splitValue, widthForKey } from './splitWidth'
import { cx } from './ui'

const STORAGE_KEY = 'table-maker:split-left'

// AI generated by: Claude Code / claude-opus-5-5
// Prompt: "make sure the layout stays fixed verticaly, make the left and right pane scrollable instead"
// Changes: Scrollable column of a fill layout (no bottom margin under the last panel, scrolling does not chain to the page).
const pane = 'lg:min-h-0 lg:overflow-y-auto lg:overscroll-contain lg:rounded-2xl lg:[&>*>*:last-child]:mb-0'

// AI generated by: Claude Code / claude-opus-5-5
// Prompt: "also teh definition and LL should have the horizonal resizing separate not linked to each other"
// Changes: Width is kept per layout id (Definícia and LL each have their own); tabs without an id share the default.
type Group = { width: number | null; loaded: boolean; listeners: Set<(w: number | null) => void> }
const groups = new Map<string, Group>()

function group(id: string) {
  let g = groups.get(id)
  if (!g) groups.set(id, (g = { width: null, loaded: false, listeners: new Set() }))
  return g
}

const storageKey = (id: string) => (id === 'default' ? STORAGE_KEY : `${STORAGE_KEY}:${id}`)

function readStored(id: string) {
  try {
    const n = Number(localStorage.getItem(storageKey(id)))
    return Number.isFinite(n) && n > 0 ? n : null
  } catch {
    return null
  }
}

function storeWidth(id: string, w: number | null) {
  const g = group(id)
  g.width = w
  g.listeners.forEach((fn) => fn(w))
  try {
    if (w === null) localStorage.removeItem(storageKey(id))
    else localStorage.setItem(storageKey(id), String(Math.round(w)))
  } catch {
    // Storage unavailable (private window etc.) – the width just is not remembered.
  }
}

// AI generated by: Claude Code / claude-opus-5-5
// Prompt: "also teh definition and LL should have the horizonal resizing separate not linked to each other"
// Changes: Optional id – layouts with different ids are resized independently.
// AI generated by: Claude Code / claude-opus-5-5
// Prompt: "make sure the layout stays fixed verticaly, make the left and right pane scrollable instead"
// Changes: fill – on wide screens the layout takes the parent's height and each column scrolls on its own.
export function SplitLayout({ id = 'default', fill = false, children }: { id?: string; fill?: boolean; children: ReactNode }) {
  const [left, right] = Children.toArray(children)
  const box = useRef<HTMLDivElement>(null)
  const leftId = useId()
  const [width, setWidth] = useState<number | null>(() => group(id).width)
  const [total, setTotal] = useState(1200)
  const [dragging, setDragging] = useState(false)
  // Drag state outside React: one layout read on pointerdown, at most one style write per frame.
  const drag = useRef<{ originX: number; total: number; x: number; moved: boolean; frame: number } | null>(null)

  useEffect(() => {
    const g = group(id)
    if (!g.loaded) {
      g.width = readStored(id)
      g.loaded = true
    }
    setWidth(g.width)
    g.listeners.add(setWidth)
    return () => void g.listeners.delete(setWidth)
  }, [id])

  // Layout width for the limits and the announced percentage (only changes on resize).
  useEffect(() => {
    const el = box.current
    if (!el) return
    const ro = new ResizeObserver(() => setTotal(el.clientWidth || 1200))
    ro.observe(el)
    return () => ro.disconnect()
  }, [])

  const current = width ?? DEFAULT_LEFT
  const value = splitValue(current, total)

  const onPointerDown = (e: PointerEvent<HTMLDivElement>) => {
    if (e.button !== 0 || !box.current) return
    e.preventDefault()
    e.currentTarget.setPointerCapture(e.pointerId)
    const rect = box.current.getBoundingClientRect()
    // 8px: half of the divider, so the pointer stays on the divider's centre.
    drag.current = { originX: rect.left + 8, total: rect.width, x: e.clientX, moved: false, frame: 0 }
    setDragging(true)
  }
  const onPointerMove = (e: PointerEvent<HTMLDivElement>) => {
    const d = drag.current
    if (!d || !e.currentTarget.hasPointerCapture(e.pointerId)) return
    d.x = e.clientX
    d.moved = true
    if (d.frame) return
    d.frame = requestAnimationFrame(() => {
      d.frame = 0
      box.current?.style.setProperty('--split-left', `${clampWidth(d.x - d.originX, splitBounds(d.total))}px`)
    })
  }
  const onLostPointerCapture = () => {
    const d = drag.current
    drag.current = null
    setDragging(false)
    if (!d) return
    if (d.frame) cancelAnimationFrame(d.frame)
    // A plain click (or the first half of a double-click) does not change the width.
    if (!d.moved) return
    const final = clampWidth(d.x - d.originX, splitBounds(d.total))
    // Write it here too: React skips the style update when the final width equals the previous state.
    box.current?.style.setProperty('--split-left', `${final}px`)
    storeWidth(id, final)
  }
  const onKeyDown = (e: KeyboardEvent<HTMLDivElement>) => {
    const next = widthForKey(e.key, e.shiftKey, current, splitBounds(box.current?.clientWidth ?? total))
    if (next === undefined) return
    e.preventDefault()
    storeWidth(id, next)
  }

  return (
    <div
      ref={box}
      style={{ ['--split-left' as string]: `${current}px` }}
      className={cx(
        'grid items-start gap-4 lg:grid-cols-[min(var(--split-left),calc(100%-376px))_auto_minmax(0,1fr)] lg:gap-x-1',
        fill && 'lg:h-full lg:min-h-0 lg:grid-rows-[minmax(0,1fr)] lg:items-stretch',
        dragging && 'cursor-col-resize select-none',
      )}
    >
      <div id={leftId} className={cx('min-w-0', fill && pane)}>
        {left}
      </div>
      <div
        role="separator"
        aria-orientation="vertical"
        aria-label="Šírka ľavého stĺpca"
        aria-controls={leftId}
        aria-valuenow={value.now}
        aria-valuemin={value.min}
        aria-valuemax={value.max}
        aria-valuetext={value.text}
        tabIndex={0}
        title="Ťahaj alebo použi šípky (Home/End = najužší/najširší) · dvojklik = pôvodná šírka"
        onPointerDown={onPointerDown}
        onPointerMove={onPointerMove}
        onLostPointerCapture={onLostPointerCapture}
        onDoubleClick={() => storeWidth(id, null)}
        onKeyDown={onKeyDown}
        className="group hidden w-3 cursor-col-resize touch-none self-stretch justify-center rounded-full select-none focus-visible:bg-indigo-400/10 focus-visible:outline-2 focus-visible:outline-offset-0 focus-visible:outline-indigo-400 lg:flex"
      >
        <span
          className={cx(
            'w-px rounded-full transition-colors group-hover:w-0.5 group-hover:bg-indigo-400/60 group-focus-visible:w-0.5 group-focus-visible:bg-indigo-400/80',
            dragging ? 'w-0.5 bg-indigo-400' : 'bg-white/10',
          )}
        />
      </div>
      <div className={cx('min-w-0', fill && pane)}>{right}</div>
    </div>
  )
}
